package quarry

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"os"
	"path/filepath"
	"sync"
	"sync/atomic"
	"time"

	"bonjoski/argus/internal/procident"
)

const maxQuarryAlertFrameBytes = 1 << 20

// Dispatcher broadcasts security alerts generated by Quarry over a local Unix domain socket.
type Dispatcher struct {
	mu          sync.RWMutex
	socketPath  string
	listener    net.Listener
	subscribers map[net.Conn]chan []byte
	stopCh      chan struct{}
	running     bool

	totalDispatched atomic.Int64
	totalDropped    atomic.Int64
}

// NewDispatcher creates a new alert dispatcher targeting the given socket path.
func NewDispatcher(socketPath string) *Dispatcher {
	return &Dispatcher{
		socketPath:  socketPath,
		subscribers: make(map[net.Conn]chan []byte),
		stopCh:      make(chan struct{}),
	}
}

// Start begins listening on the Unix domain socket and accepting subscriber connections.
func (d *Dispatcher) Start() error {
	d.mu.Lock()
	if d.running {
		d.mu.Unlock()
		return nil
	}

	if d.socketPath == "" {
		d.mu.Unlock()
		return errors.New("socket path cannot be empty")
	}

	// Ensure parent directory exists with restrictive permissions
	parentDir := filepath.Dir(d.socketPath)
	if err := os.MkdirAll(parentDir, 0700); err != nil {
		d.mu.Unlock()
		return fmt.Errorf("failed to create dispatcher socket directory %s: %w", parentDir, err)
	}

	// Safely remove stale socket (refusing symlinks, directories, or foreign-owned files)
	if fi, err := os.Lstat(d.socketPath); err == nil {
		if fi.Mode()&os.ModeSymlink != 0 {
			d.mu.Unlock()
			return fmt.Errorf("refusing to remove symlinked dispatcher socket %s", d.socketPath)
		}
		if fi.IsDir() || (fi.Mode()&os.ModeSocket == 0 && fi.Size() > 0) {
			d.mu.Unlock()
			return fmt.Errorf("refusing to overwrite non-socket file %s", d.socketPath)
		}
		if err := procident.VerifyFileOwnerAndNotSymlink(d.socketPath); err != nil {
			d.mu.Unlock()
			return fmt.Errorf("refusing to remove foreign stale dispatcher socket %s: %w", d.socketPath, err)
		}
		if err := os.Remove(d.socketPath); err != nil && !os.IsNotExist(err) {
			d.mu.Unlock()
			return fmt.Errorf("failed to remove stale dispatcher socket %s: %w", d.socketPath, err)
		}
	}

	l, err := net.Listen("unix", d.socketPath)
	if err != nil {
		d.mu.Unlock()
		return fmt.Errorf("failed to listen on dispatcher socket %s: %w", d.socketPath, err)
	}

	// Enforce 0600 file permissions
	if err := os.Chmod(d.socketPath, 0600); err != nil {
		_ = l.Close()
		d.mu.Unlock()
		return fmt.Errorf("failed to enforce 0600 permissions on %s: %w", d.socketPath, err)
	}

	d.listener = l
	d.running = true
	d.stopCh = make(chan struct{})
	d.mu.Unlock()

	go d.acceptLoop(l)

	return nil
}

func (d *Dispatcher) acceptLoop(l net.Listener) {
	for {
		conn, err := l.Accept()
		if err != nil {
			select {
			case <-d.stopCh:
				return
			default:
				if errors.Is(err, net.ErrClosed) {
					return
				}
				continue
			}
		}

		if err := procident.VerifyUnixPeerUID(conn); err != nil {
			_ = conn.Close()
			continue
		}

		d.addSubscriber(conn)
	}
}

func (d *Dispatcher) addSubscriber(conn net.Conn) {
	d.mu.Lock()
	defer d.mu.Unlock()

	if !d.running {
		_ = conn.Close()
		return
	}

	ch := make(chan []byte, 100)
	d.subscribers[conn] = ch

	go d.subscriberWorker(conn, ch)
}

func (d *Dispatcher) subscriberWorker(conn net.Conn, ch chan []byte) {
	defer func() {
		_ = conn.Close()
		d.removeSubscriber(conn)
	}()

	for {
		select {
		case msg, ok := <-ch:
			if !ok {
				return
			}
			_ = conn.SetWriteDeadline(time.Now().Add(50 * time.Millisecond))
			if _, err := conn.Write(msg); err != nil {
				return
			}
		case <-d.stopCh:
			return
		}
	}
}

func (d *Dispatcher) removeSubscriber(conn net.Conn) {
	d.mu.Lock()
	defer d.mu.Unlock()
	if ch, ok := d.subscribers[conn]; ok {
		close(ch)
		delete(d.subscribers, conn)
	}
}

// Broadcast dispatches an Alert to all active subscriber connections in sub-millisecond time.
func (d *Dispatcher) Broadcast(alert *Alert) error {
	if alert == nil {
		return errors.New("cannot broadcast nil alert")
	}

	data, err := json.Marshal(alert)
	if err != nil {
		return fmt.Errorf("failed to marshal alert: %w", err)
	}
	payload := append(data, '\n')

	d.mu.RLock()
	defer d.mu.RUnlock()

	d.totalDispatched.Add(1)

	// ONLY push outbound when this Dispatcher is NOT running as the in-process socket listener (ARG-07).
	// Dialing d.socketPath when d.running == true would connect to our own acceptLoop!
	if !d.running && len(d.subscribers) == 0 && d.socketPath != "" {
		go d.pushToSocket(d.socketPath, payload)
		return nil
	}

	for _, ch := range d.subscribers {
		select {
		case ch <- payload:
		default:
			d.totalDropped.Add(1)
		}
	}

	return nil
}

func (d *Dispatcher) pushToSocket(sockPath string, payload []byte) {
	d.mu.RLock()
	isSelfListening := d.running && d.socketPath == sockPath
	d.mu.RUnlock()
	if isSelfListening {
		return
	}

	if err := procident.VerifyFileOwnerAndNotSymlink(sockPath); err != nil {
		return
	}

	conn, err := net.DialTimeout("unix", sockPath, 100*time.Millisecond)
	if err != nil {
		return
	}
	defer conn.Close()

	if err := procident.VerifyUnixPeerUID(conn); err != nil {
		return
	}

	_ = conn.SetWriteDeadline(time.Now().Add(50 * time.Millisecond))
	_, _ = conn.Write(payload)
}

// Stop closes the Unix listener and terminates all subscriber connections.
func (d *Dispatcher) Stop() error {
	d.mu.Lock()
	if !d.running {
		d.mu.Unlock()
		return nil
	}

	d.running = false
	close(d.stopCh)

	var stopErr error
	if d.listener != nil {
		if err := d.listener.Close(); err != nil && !errors.Is(err, net.ErrClosed) {
			stopErr = err
		}
	}

	for conn, ch := range d.subscribers {
		close(ch)
		_ = conn.Close()
		delete(d.subscribers, conn)
	}

	if d.socketPath != "" {
		if err := os.Remove(d.socketPath); err != nil && !os.IsNotExist(err) && stopErr == nil {
			stopErr = fmt.Errorf("failed to remove dispatcher socket %s: %w", d.socketPath, err)
		}
	}

	d.mu.Unlock()
	return stopErr
}

// SubscribersCount returns the number of active subscriber connections.
func (d *Dispatcher) SubscribersCount() int {
	d.mu.RLock()
	defer d.mu.RUnlock()
	return len(d.subscribers)
}

// TotalDispatched returns the total number of broadcast attempts.
func (d *Dispatcher) TotalDispatched() int64 {
	return d.totalDispatched.Load()
}

// ListenAlerts is a client helper function that connects to a Dispatcher socket and yields alerts.
func ListenAlerts(ctx context.Context, socketPath string) (<-chan *Alert, error) {
	if err := procident.VerifyFileOwnerAndNotSymlink(socketPath); err != nil {
		return nil, fmt.Errorf("unsafe quarry dispatcher socket %s: %w", socketPath, err)
	}

	conn, err := net.DialTimeout("unix", socketPath, 500*time.Millisecond)
	if err != nil {
		return nil, fmt.Errorf("failed to connect to quarry dispatcher socket %s: %w", socketPath, err)
	}

	if err := procident.VerifyUnixPeerUID(conn); err != nil {
		_ = conn.Close()
		return nil, fmt.Errorf("unauthorized peer UID on dispatcher socket %s: %w", socketPath, err)
	}

	alertCh := make(chan *Alert, 50)
	go func() {
		defer close(alertCh)
		defer conn.Close()

		limited := io.LimitReader(conn, maxQuarryAlertFrameBytes+1)
		lr, _ := limited.(*io.LimitedReader)
		reader := bufio.NewReader(limited)
		for {
			select {
			case <-ctx.Done():
				return
			default:
				if lr != nil {
					lr.N = maxQuarryAlertFrameBytes + 1
				}
				_ = conn.SetReadDeadline(time.Now().Add(1 * time.Second))
				line, err := reader.ReadBytes('\n')
				if len(line) > maxQuarryAlertFrameBytes || (errors.Is(err, io.EOF) && lr != nil && lr.N == 0) {
					return
				}
				if err != nil {
					if errors.Is(err, os.ErrDeadlineExceeded) || errors.Is(err, context.DeadlineExceeded) {
						continue
					}
					return
				}
				if len(line) == 0 {
					continue
				}

				var a Alert
				if err := json.Unmarshal(line, &a); err == nil {
					select {
					case alertCh <- &a:
					case <-ctx.Done():
						return
					}
				}
			}
		}
	}()

	return alertCh, nil
}
